#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using Sim.Game;
using Sim.Vehicles;
using Sim.Vehicles.Editor;
using Sim.World;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;

namespace BuildTools
{
    /// <summary>
    /// Turns this folder into a working DARK NOTE project: imports the 60-car roster,
    /// creates the bootstrap scene, and applies the Android player settings.
    /// Everything is generated by code so no hand-written .unity/.asset YAML can rot.
    /// </summary>
    public static class ProjectSetup
    {
        public const string ProductName = "DARK NOTE";
        public const string CompanyName = "Alsphalt";
        public const string BundleId = "com.alsphalt.darknote";
        public const string VersionName = "1.1";
        public const int VersionCode = 2;

        public const string ScenePath = "Assets/Scenes/Main.unity";
        public const string CatalogPath = "Assets/Content/VehicleCatalog.asset";
        public const string CitySettingsPath = "Assets/Content/CitySettings.asset";
        public const string CsvPath = "Assets/Content/vehicles.csv";

        public static string ProjectRoot => Directory.GetParent(Application.dataPath).FullName;

        static string Abs(string assetPath) =>
            Path.Combine(ProjectRoot, assetPath.Replace('/', Path.DirectorySeparatorChar));

        [MenuItem("Sim/Setup/Configure Project (roster, scene, Android settings)", false, 1)]
        public static void Configure()
        {
            try
            {
                var catalog = EnsureRoster();
                EnsureScene(catalog);
                ApplyPlayerSettings();
                AssetDatabase.SaveAssets();
                AssetDatabase.Refresh();
                Debug.Log("DARK NOTE: configured. Scene: " + ScenePath + ", cars: " + catalog.vehicles.Length);
            }
            catch (Exception e)
            {
                Debug.LogError("DARK NOTE setup failed: " + e);
                if (Application.isBatchMode) EditorApplication.Exit(1);
                else throw;
            }
        }

        public static VehicleCatalog EnsureRoster()
        {
            var catalog = AssetDatabase.LoadAssetAtPath<VehicleCatalog>(CatalogPath);
            if (catalog != null && catalog.vehicles != null && catalog.vehicles.Length > 0) return catalog;

            string csv = Abs(CsvPath);
            if (!File.Exists(csv))
                throw new FileNotFoundException("Vehicle roster CSV is missing: " + csv, csv);

            Debug.Log("DARK NOTE: importing roster from " + csv);
            VehicleCsvImporter.Import(csv);
            AssetDatabase.Refresh();

            catalog = AssetDatabase.LoadAssetAtPath<VehicleCatalog>(CatalogPath);
            if (catalog == null || catalog.vehicles == null || catalog.vehicles.Length == 0)
                throw new Exception("Roster import did not produce " + CatalogPath);
            return catalog;
        }

        public static void EnsureScene(VehicleCatalog catalog)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(Abs(ScenePath)));
            Directory.CreateDirectory(Path.GetDirectoryName(Abs(CitySettingsPath)));

            var city = AssetDatabase.LoadAssetAtPath<CityGeneratorSettings>(CitySettingsPath);
            if (city == null)
            {
                city = ScriptableObject.CreateInstance<CityGeneratorSettings>();
                city.name = "CitySettings";
                AssetDatabase.CreateAsset(city, CitySettingsPath);
            }

            if (!File.Exists(Abs(ScenePath)))
            {
                var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
                var go = new GameObject("Game");
                var boot = go.AddComponent<GameBootstrap>();
                boot.catalog = catalog;
                boot.citySettings = city;
                EditorSceneManager.MarkSceneDirty(scene);
                if (!EditorSceneManager.SaveScene(scene, ScenePath))
                    throw new Exception("Could not save " + ScenePath);
                Debug.Log("DARK NOTE: created " + ScenePath);
            }

            EditorBuildSettings.scenes = new[] { new EditorBuildSettingsScene(ScenePath, true) };
        }

        public static void ApplyPlayerSettings()
        {
            PlayerSettings.companyName = CompanyName;
            PlayerSettings.productName = ProductName;
            PlayerSettings.SetApplicationIdentifier(NamedBuildTarget.Android, BundleId);
            PlayerSettings.bundleVersion = VersionName;
            PlayerSettings.Android.bundleVersionCode = VersionCode;

            PlayerSettings.Android.minSdkVersion = AndroidSdkVersions.AndroidApiLevel24;
            PlayerSettings.Android.targetSdkVersion = AndroidSdkVersions.AndroidApiLevelAuto;

            PlayerSettings.SetScriptingBackend(NamedBuildTarget.Android, ScriptingImplementation.IL2CPP);
            PlayerSettings.SetIl2CppCompilerConfiguration(BuildTargetGroup.Android, Il2CppCompilerConfiguration.Release);
            PlayerSettings.SetManagedStrippingLevel(NamedBuildTarget.Android, ManagedStrippingLevel.Low);
            PlayerSettings.Android.targetArchitectures = AndroidArchitecture.ARM64;

            PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.Android, false);
            PlayerSettings.SetGraphicsAPIs(BuildTarget.Android,
                new[] { GraphicsDeviceType.Vulkan, GraphicsDeviceType.OpenGLES3 });

            PlayerSettings.colorSpace = ColorSpace.Linear;
            PlayerSettings.defaultInterfaceOrientation = UIOrientation.AutoRotation;
            PlayerSettings.allowedAutorotateToLandscapeLeft = true;
            PlayerSettings.allowedAutorotateToLandscapeRight = true;
            PlayerSettings.allowedAutorotateToPortrait = false;
            PlayerSettings.allowedAutorotateToPortraitUpsideDown = false;

            QualitySettings.shadowDistance = 70f;
            QualitySettings.vSyncCount = 0;
        }

        [MenuItem("Sim/Setup/Optional: create and assign a URP asset", false, 20)]
        public static void EnableUrpMenu() => TryEnableUrp(true);

        /// <summary>
        /// Creates a URP asset and assigns it as the render pipeline. Done through reflection so the
        /// project still compiles and runs when the URP package is absent, and so an API change in
        /// URP cannot break the build. Returns false when URP is not installed or creation failed.
        /// </summary>
        public static bool TryEnableUrp(bool verbose)
        {
            if (GraphicsSettings.defaultRenderPipeline != null)
            {
                if (verbose) Debug.Log("A render pipeline asset is already assigned: " + GraphicsSettings.defaultRenderPipeline.name);
                return true;
            }

            try
            {
                var asm = AppDomain.CurrentDomain.GetAssemblies()
                    .FirstOrDefault(a => a.GetName().Name == "Unity.RenderPipelines.Universal.Runtime");
                var assetType = asm?.GetType("UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset");
                var dataType = asm?.GetType("UnityEngine.Rendering.Universal.UniversalRendererData");
                if (assetType == null || dataType == null)
                {
                    if (verbose) Debug.LogWarning("URP package not found. Install com.unity.render-pipelines.universal first.");
                    return false;
                }

                Directory.CreateDirectory(Abs("Assets/Settings"));

                var data = ScriptableObject.CreateInstance(dataType);
                data.name = "DarkNoteRenderer";
                AssetDatabase.CreateAsset(data, "Assets/Settings/DarkNoteRenderer.asset");

                var create = assetType.GetMethods()
                    .FirstOrDefault(m => m.Name == "Create" && m.IsStatic && m.GetParameters().Length == 1);
                if (create == null)
                {
                    if (verbose) Debug.LogWarning("URP Create() not found; create the asset from Assets > Create > Rendering manually.");
                    return false;
                }

                var asset = create.Invoke(null, new object[] { data }) as ScriptableObject;
                if (asset == null) return false;
                asset.name = "DarkNoteUrp";
                AssetDatabase.CreateAsset(asset, "Assets/Settings/DarkNoteUrp.asset");

                var pipeline = asset as RenderPipelineAsset;
                if (pipeline == null) return false;
                GraphicsSettings.defaultRenderPipeline = pipeline;
                QualitySettings.renderPipeline = pipeline;

                AssetDatabase.SaveAssets();
                AssetDatabase.Refresh();
                if (verbose) Debug.Log("URP asset created and assigned: Assets/Settings/DarkNoteUrp.asset");
                return true;
            }
            catch (Exception e)
            {
                if (verbose) Debug.LogWarning("URP setup skipped: " + e.Message);
                return false;
            }
        }
    }
}
#endif
